components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px;
  border-radius: 12px;
  border: 1px solid #1b61c9;
  background: #1b61c9;
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 150ms cubic-bezier(0.2, 0, 0, 1), transform 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn-primary:hover {
  background: #254fad;
}
.ds-btn-primary:active {
  transform: translateY(1px);
}
.ds-btn-primary:focus-visible {
  box-shadow: 0 0 0 3px color-mix(in oklab, #1b61c9, transparent 70%);
  outline: none;
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px;
  border-radius: 12px;
  border: 1px solid #e0e2e6;
  background: transparent;
  color: #181d26;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 150ms cubic-bezier(0.2, 0, 0, 1), background 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-btn-secondary:hover {
  border-color: #181d26;
  background: #eef0f3;
}
.ds-btn-secondary:focus-visible {
  box-shadow: 0 0 0 3px color-mix(in oklab, #1b61c9, transparent 70%);
  outline: none;
}

.ds-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: 9999px;
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.ds-pill-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.ds-pill-success {
  background: rgba(0, 100, 0, 0.12);
  color: #006400;
}
.ds-pill-danger {
  background: rgba(220, 38, 38, 0.10);
  color: #a10d3d;
}
.ds-pill-warn {
  background: rgba(234, 179, 8, 0.12);
  color: #8a6500;
}

.ds-sidebar {
  background: #1b61c9;
  color: #ffffff;
  padding: 16px;
  width: 240px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}
.ds-sidebar-logo {
  font-family: Haas, -apple-system, system-ui, Segoe UI, Roboto, sans-serif;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.01em;
  padding: 8px 8px 24px;
  border-bottom: 1px solid rgba(255,255,255,0.15);
  margin-bottom: 16px;
}
.ds-sidebar-section {
  margin-bottom: 24px;
}
.ds-sidebar-label {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 8px;
  padding: 0 8px;
}
.ds-sidebar-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 8px;
  border-radius: 12px;
  font-size: 14px;
  color: rgba(255,255,255,0.75);
  text-decoration: none;
  cursor: pointer;
  transition: background 200ms cubic-bezier(0.2, 0, 0, 1), color 200ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-sidebar-item:hover {
  background: rgba(255,255,255,0.1);
  color: #ffffff;
}
.ds-sidebar-item-active {
  background: rgba(27, 97, 201, 0.25);
  color: #ffffff;
}
.ds-sidebar-count {
  margin-left: auto;
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  background: rgba(255,255,255,0.15);
  padding: 2px 6px;
  border-radius: 8px;
}

.ds-field {
  margin-bottom: 20px;
}
.ds-field-label {
  display: block;
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: rgba(4, 14, 32, 0.69);
  margin-bottom: 8px;
}
.ds-field-input {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid #e0e2e6;
  border-radius: 12px;
  font-size: 14px;
  color: #181d26;
  background: #ffffff;
  outline: none;
  transition: border-color 150ms cubic-bezier(0.2, 0, 0, 1), box-shadow 150ms cubic-bezier(0.2, 0, 0, 1);
}
.ds-field-input::placeholder {
  color: rgba(4, 14, 32, 0.69);
}
.ds-field-input:focus {
  border-color: #1b61c9;
  box-shadow: 0 0 0 3px color-mix(in oklab, #1b61c9, transparent 70%);
}
.ds-field-hint {
  font-size: 12px;
  color: rgba(4, 14, 32, 0.69);
  margin-top: 8px;
}

.ds-stat-card {
  background: #ffffff;
  border: 1px solid #eef0f3;
  border-radius: 16px;
  padding: 16px;
}
.ds-stat-label {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  color: rgba(4, 14, 32, 0.69);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.ds-stat-value {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #181d26;
  line-height: 1;
}
.ds-stat-unit {
  font-size: 0.5em;
  opacity: 0.5;
}
.ds-stat-sub {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  color: rgba(4, 14, 32, 0.69);
  margin-top: 8px;
}
.ds-stat-trend-up {
  color: #006400;
}
.ds-stat-trend-down {
  color: #dc2626;
}

.ds-ai-insight {
  background: linear-gradient(135deg, rgba(74, 20, 75, 0.04), rgba(74, 20, 75, 0.08));
  border: 1px solid rgba(74, 20, 75, 0.15);
  border-radius: 16px;
  padding: 16px;
}
.ds-ai-insight-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}
.ds-ai-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: #1b61c9;
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 9999px;
}
.ds-ai-insight-body {
  font-size: 14px;
  line-height: 1.6;
  color: #181d26;
}
.ds-ai-insight-body strong {
  color: #1b61c9;
}
.ds-ai-insight-body code {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  background: rgba(74, 20, 75, 0.08);
  padding: 1px 5px;
  border-radius: 3px;
}

.ds-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}
.ds-table th {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 2px solid #181d26;
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(4, 14, 32, 0.69);
}
.ds-table td {
  padding: 12px 12px;
  border-bottom: 1px solid #eef0f3;
  vertical-align: middle;
}
.ds-table tbody tr:hover {
  background: #ffffff;
}
.ds-table-num {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.ds-table-name {
  font-weight: 600;
}
.ds-table-mono {
  font-family: ui-monospace, SF Mono, JetBrains Mono, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  color: rgba(4, 14, 32, 0.69);
}
.ds-table-clickable {
  cursor: pointer;
}
.ds-table-clickable:hover {
  color: #1b61c9;
}
